"""A stand-in for kith serve's loopback API, for the difftest cases of kith-people (invite add|ls|revoke). Binds an
ephemeral port, writes it to DIR/port, logs every call to DIR/calls.log (never the token), and exits when DIR/port is
removed (the runner deletes the case's folder when it is done)."""
import json
import os
import select
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer

DIR = sys.argv[1]
TOKEN = open(os.path.join(DIR, 'token')).read().strip()
REVOKED = set()
MADE = []


def answer(method, body):
    """-> (status, raw bytes)"""
    if method == 'createInvite':
        name = body.get('name') or ''
        if name == 'Boom':
            return 409, json.dumps({'error': 'name taken: Boom'})
        if name == 'Teapot':
            return 500, 'oops, not json'
        if name == 'Blank':
            return 400, json.dumps({'error': ''})
        if name == 'Nothing':
            return 200, 'null'
        if name == 'Broken':
            return 200, '{not json'
        n = len(MADE) + 1
        MADE.append(body)
        return 200, json.dumps({
            'inviteId': f'inv_{n}', 'personId': body.get('personId') or 'p-' + name.lower(),
            'link': f'https://kith.example/join/inv_{n}', 'expiresAt': 1793900000 + n,
            'tokenHash': 'SECRET-HASH', 'token': 'SECRET-TOKEN', 'agents': body.get('agents')})
    if method == 'invites':
        return 200, json.dumps({'invites': [
            {'inviteId': 'inv_1', 'personId': 'sam', 'agents': {'house': 'member', 'garden': 'guest'}, 'expiresAt': 1793900001,
             'tokenHash': 'SECRET-HASH', 'link': {'proof': 'SECRET-PROOF', 'url': 'https://kith.example/join/inv_1'},
             'history': [{'token_hash': 'SECRET-HASH-2', 'at': 1}]},
            {'inviteId': 'inv_2', 'personId': 'ola', 'agents': {'house': 'guest'}, 'usedAt': 1793800000, 'revokedAt': 1793800500},
            {'inviteId': 'inv_3', 'personId': 'bo', 'agents': {}, 'revokedAt': 1793800600},
            {'inviteId': 'inv_4', 'personId': 'cy'}]})
    if method == 'revokeInvite':
        iid = body.get('inviteId')
        if iid == 'inv_err':
            return 404, json.dumps({'error': 'no such invite'})
        if iid == 'inv_1' and iid not in REVOKED:
            REVOKED.add(iid)
            return 200, json.dumps({'revoked': True})
        return 200, json.dumps({'revoked': False})
    return 404, json.dumps({'error': f'no such method {method}'})


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def do_POST(self):
        raw = self.rfile.read(int(self.headers.get('Content-Length') or 0))
        method = self.path.removeprefix('/api/')
        body = json.loads(raw or b'{}')
        ok = self.headers.get('Authorization') == f'Bearer {TOKEN}'
        with open(os.path.join(DIR, 'calls.log'), 'a') as f:
            f.write(f'{method} {json.dumps(body, sort_keys=True)}{"" if ok else " (refused: bad token)"}\n')
        status, text = answer(method, body) if ok else (401, json.dumps({'error': 'bad token'}))
        data = text.encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(data)))
        self.end_headers()
        self.wfile.write(data)


srv = HTTPServer(('127.0.0.1', 0), H)
with open(os.path.join(DIR, 'port.tmp'), 'w') as f:
    f.write(str(srv.server_address[1]))
os.rename(os.path.join(DIR, 'port.tmp'), os.path.join(DIR, 'port'))
while os.path.exists(os.path.join(DIR, 'port')):
    if select.select([srv.socket], [], [], 0.3)[0]:
        srv.handle_request()

